// The server's import planner writes what the desktop writes (INT-02 A2,
// ADR-0052 §2). `src-tauri/tests/fixtures/api-import-interop.json` holds, for
// each input document, the shard and result documents `import.rs` stored and
// synced (generated by `api_import_interop_vectors`); the server's planner,
// given the same document and shard id, must produce the same ids and the
// same content. Only the bookkeeping keys differ (who, when, the clock and
// the location: outside the append-only content, `NON_CONTENT_KEYS`).
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import * as formats from "@pharos/formats";
import { findingPayload, metricPayload, planFindings, planImport, resultPayload } from "../src/modules/api/importPlan";

const FIXTURE = new URL("../../src-tauri/tests/fixtures/api-import-interop.json", import.meta.url);

interface Case {
  name: string;
  doc: Record<string, unknown>;
  sha256: string;
  runId: string;
  shardId: string;
  shard: Record<string, unknown>;
  results: Record<string, unknown>[];
  findings?: Record<string, unknown>[];
  metrics?: Record<string, unknown>[];
  warnings: { code: string; testKey: string | null; detail: string | null }[];
}

const cases = (JSON.parse(readFileSync(FIXTURE, "utf8")) as { cases: Case[] }).cases;
const BOOKKEEPING = ["workspaceId", "projectId", "createdBy", "createdAt", "hlc"];
const content = (p: Record<string, unknown>) => Object.fromEntries(Object.entries(p).filter(([k]) => !BOOKKEEPING.includes(k)));

describe("the server's import planner writes what the desktop writes", () => {
  it("has vectors for every format and the corner cases", () => {
    expect(cases.map((c) => c.name)).toEqual(
      expect.arrayContaining(["single/ctrf", "single/pw-junit", "single/cucumber-messages", "edge", "sarif/trivy", "axe/checkout", "k6/summary", "findings-edge"]),
    );
  });

  it.each(cases.map((c) => [c.name, c] as const))("%s", (_name, c) => {
    const plan = planImport(c.doc, c.shardId, formats);
    const ctx = { projectId: "p", runId: c.runId, shardId: c.shardId, executedBy: plan.executedBy, userId: "u", at: "t", hlc: "h" };
    const mine = plan.results.map((r) => content(resultPayload(r, ctx))).sort((a, b) => String(a.id).localeCompare(String(b.id)));
    const theirs = c.results.map(content).sort((a, b) => String(a.id).localeCompare(String(b.id)));
    expect(mine).toEqual(theirs);
    expect({
      sourceFormat: plan.format,
      formatVersion: plan.formatVersion,
      normalizerVersion: plan.normalizerVersion,
      shardIndex: plan.shardIndex,
      shardTotal: plan.shardTotal,
    }).toEqual({
      sourceFormat: c.shard.sourceFormat,
      formatVersion: c.shard.formatVersion,
      normalizerVersion: c.shard.normalizerVersion,
      shardIndex: c.shard.shardIndex,
      shardTotal: c.shard.shardTotal,
    });
    // Findings and metrics (A2b): the same ids and content as findings.rs.
    const fm = planFindings(c.doc, c.shardId, formats);
    const byId = (a: Record<string, unknown>, b: Record<string, unknown>) => String(a.id).localeCompare(String(b.id));
    const fctx = { projectId: "p", runId: c.runId, shardId: c.shardId, userId: "u", at: "t", hlc: "h" };
    expect(fm.findings.map((f) => content(findingPayload(f, fctx))).sort(byId)).toEqual((c.findings ?? []).map(content).sort(byId));
    expect(fm.metrics.map((m) => content(metricPayload(m, fctx))).sort(byId)).toEqual((c.metrics ?? []).map(content).sort(byId));
    expect([...plan.warnings, ...fm.warnings].map((w) => ({ code: w.code, testKey: w.testKey, detail: w.detail }))).toEqual(c.warnings);
  });
});
